using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class VillageConsultationTests
{
    static readonly EntityId Site=new("site:kofu");
    internal static WorldSession Start(string person="person:shingen",ulong seed=42)=>new(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],person,seed,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:VillageConsultation.Policy));
    static CommandResult Act(WorldSession s,VillageAction action,EntityId? q=null,long amount=0,string? id=null)=>s.ConsultVillage(new(new(id??"request:village/"+s.Revision),action,Site,q,amount),s.PlayerControl,s.Revision);
    static void Accepted(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static EntityId Propose(WorldSession s,bool water=false,long amount=200){Accepted(Act(s,water?VillageAction.ProposeWater:VillageAction.ProposeRelief,amount:amount));return s.DiagnosticSnapshot().Villages!.Proposals.Last().Id;}
    static EntityId Agree(WorldSession s,bool water=false,long amount=200){var q=Propose(s,water,amount);Accepted(Act(s,VillageAction.Confirm,q));return q;}
    static void Advance(WorldSession s,long at){while(s.Seconds<at){long old=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Assert.True(s.Seconds>old);}}
    static CommunityAccounts A(WorldSession s)=>s.DiagnosticSnapshot().Communities!.Accounts.Single(a=>a.Site==Site);
    [Fact]public void OrganizationMembersRepresentativeAndSiteHaveDifferentIdentity(){var s=Start();var org=s.DiagnosticSnapshot().Villages!.Organizations.Single(o=>o.Site==Site);Assert.NotEqual(org.Id,Site);Assert.Equal(2,org.Members.Select(m=>m.Id).Distinct().Count());Assert.DoesNotContain(s.PlayerControl,org.Members.Select(m=>m.Id));Assert.Equal(3,s.DiagnosticSnapshot().Villages!.Organizations.Length);}
    [Fact]public void PromiseDoesNotMoveRiceRolesOrLabor(){var s=Start();var before=s.DiagnosticSnapshot();Agree(s,true);var after=s.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(before.Communities),ContractJson.Write(after.Communities));Assert.Equal(ContractJson.Write(before.ServiceBonds),ContractJson.Write(after.ServiceBonds));Assert.Equal(ContractJson.Write(before.LandRights),ContractJson.Write(after.LandRights));Assert.Equal(ContractJson.Write(before.Units),ContractJson.Write(after.Units));}
    [Fact]public void WaterStartsOnlyFromAgreementAndFinishesAfterActualSevenDays(){var s=Start();Assert.Equal(ResultCode.NotAvailable,s.ManageCommunity(new(new("request:water-bypass"),Site,EconomyAction.ImproveWater,200),s.PlayerControl,s.Revision).Code);var q=Agree(s,true);Accepted(Act(s,VillageAction.Deliver,q,200));Assert.Equal(2800,A(s).HouseRice);Assert.Equal(20,A(s).Reserved);Assert.Contains("工事中",s.VillageView()!.Promises.Single().Status);Advance(s,7*86400);Assert.Equal(110,A(s).Water);Assert.Equal("工事完了",s.VillageView()!.Promises.Single().Status);Assert.Equal(0,A(s).Reserved);}
    [Fact]public void PartialReliefMovesOnlyActualAmountAndCannotOverdeliver(){var s=Start();var q=Agree(s,amount:300);Accepted(Act(s,VillageAction.Deliver,q,100));Assert.Equal(2900,A(s).HouseRice);Assert.Equal(100,s.VillageView()!.Promises.Single().Delivered);Assert.Equal(ResultCode.NotAvailable,Act(s,VillageAction.Deliver,q,201).Code);Accepted(Act(s,VillageAction.Deliver,q,200));Assert.Equal(2700,A(s).HouseRice);Assert.Equal("救済受領済み",s.VillageView()!.Promises.Single().Status);Assert.Equal(ResultCode.NotAvailable,Act(s,VillageAction.Deliver,q,1).Code);}
    [Fact]public void DeadlineIsInclusiveThenLateDeliveryCannotConsumeRice(){var s=Start();var q=Agree(s);Advance(s,7*86400);Accepted(Act(s,VillageAction.Deliver,q,100));Advance(s,7*86400+1);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,VillageAction.Deliver,q,100).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Contains("期限超過",s.VillageView()!.Promises.Single().Status);}
    [Fact]public void QuoteExpiryDoesNotBecomePromise(){var s=Start();var q=Propose(s);Advance(s,86401);Assert.Equal(ResultCode.NotAvailable,Act(s,VillageAction.Confirm,q).Code);Assert.Empty(s.VillageView()!.Promises);}
    [Fact]public void RepresentativeTurnInvalidatesUnconfirmedReply(){var s=Start();Advance(s,30*86400-10);var q=Propose(s);var old=s.VillageView()!.Representative;Advance(s,30*86400);Assert.NotEqual(old,s.VillageView()!.Representative);Assert.Equal(ResultCode.NotAvailable,Act(s,VillageAction.Confirm,q).Code);q=Propose(s);Accepted(Act(s,VillageAction.Confirm,q));}
    [Fact]public void RepresentativeTurnDoesNotEraseConfirmedPromise(){var s=Start();Advance(s,30*86400-10);var q=Agree(s);Advance(s,30*86400);Accepted(Act(s,VillageAction.Deliver,q,200));Assert.Equal("救済受領済み",s.VillageView()!.Promises.Single().Status);}
    [Fact]public void CompetingQuotesCannotConfirmOverlappingPromises(){var s=Start();var a=Propose(s);var b=Propose(s,true);Accepted(Act(s,VillageAction.Confirm,a));Assert.Equal(ResultCode.NotAvailable,Act(s,VillageAction.Confirm,b).Code);}
    [Fact]public void CancelPreservesDeliveredRiceAndCreatesReaction(){var s=Start();var q=Agree(s);Accepted(Act(s,VillageAction.Deliver,q,50));Accepted(Act(s,VillageAction.Cancel,q));Assert.Equal(2950,A(s).HouseRice);Assert.Equal(50,s.VillageView()!.Promises.Single().Delivered);Assert.Contains("一部履行",s.VillageView()!.Promises.Single().Status);Assert.Equal(ResultCode.NotAvailable,Act(s,VillageAction.Deliver,q,150).Code);}
    [Fact]public void RepeatedBrokenPromisesAffectNextWaterReplyButReliefRemainsPossible(){var s=Start();for(int i=0;i<2;i++){var q=Agree(s);Accepted(Act(s,VillageAction.Cancel,q));}var water=Propose(s,true);Assert.False(s.DiagnosticSnapshot().Villages!.Proposals.Last().Agreed);Assert.Contains("不信",s.VillageView()!.Reaction);Assert.Equal(ResultCode.NotAvailable,Act(s,VillageAction.Confirm,water).Code);Agree(s);}
    [Fact]public void SuccessfulReliefChangesLocalReplyWithoutGeneralLoyalty(){var s=Start();var before=s.DiagnosticSnapshot();var q=Agree(s);Accepted(Act(s,VillageAction.Deliver,q,200));Assert.Contains("評価",s.VillageView()!.Reaction);Assert.Equal(ContractJson.Write(before.ServiceBonds),ContractJson.Write(s.DiagnosticSnapshot().ServiceBonds));Assert.Equal(ContractJson.Write(before.Memberships),ContractJson.Write(s.DiagnosticSnapshot().Memberships));}
    [Fact]public void DirectEmergencyReliefIsNotAutomaticallyPromiseDelivery(){var s=Start();Agree(s);Accepted(s.ManageCommunity(new(new("request:emergency"),Site,EconomyAction.RelieveVillage,200),s.PlayerControl,s.Revision));Assert.Equal(0,s.VillageView()!.Promises.Single().Delivered);Assert.Equal(2800,A(s).HouseRice);}
    [Fact]public void InsufficientRiceDeliveryFailsAtomicallyAndKeepsPromise(){var s=Start();var q=Agree(s);Accepted(s.ManageCommunity(new(new("request:empty-vault"),Site,EconomyAction.RelieveVillage,2990),s.PlayerControl,s.Revision));var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,VillageAction.Deliver,q,200).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));Accepted(Act(s,VillageAction.Deliver,q,10));Assert.Equal(0,A(s).HouseRice);Assert.Equal(10,s.VillageView()!.Promises.Single().Delivered);}
    [Fact]public void SalaryReservedRiceCannotBeUsedForVillagePromise(){var s=Start();var worker=HistoricalHouseholdCatalog.Edition.People.Single().Id;Accepted(s.ManageSalary(new(new("request:wage-talk"),SalaryAction.Propose,worker,Site,Amount:200),s.PlayerControl,s.Revision));var salary=s.DiagnosticSnapshot().Salary!.Quotes.Last().Id;Accepted(s.ManageSalary(new(new("request:wage-agree"),SalaryAction.Confirm,worker,Site,salary),s.PlayerControl,s.Revision));Advance(s,31*86400);Accepted(s.ManageSalary(new(new("request:wage-prepare"),SalaryAction.Prepare,worker,Site,salary,200),s.PlayerControl,s.Revision));var q=Agree(s,amount:2900);Assert.Equal(ResultCode.NotAvailable,Act(s,VillageAction.Deliver,q,2900).Code);Accepted(Act(s,VillageAction.Deliver,q,2800));Assert.Equal(200,A(s).HouseRice);}
    [Fact]public void WorkRefusesHungerAndBusyLabor(){var s=Start();var q=Agree(s,true);Accepted(Act(s,VillageAction.Deliver,q,200));Propose(s,true);Assert.False(s.VillageView()!.Proposals.Last().Agreed);}
    [Fact]public void NonHeadCanHearPublicReactionButCannotPromiseHouseRice(){var s=Start(HistoricalHouseholdCatalog.Edition.People.Single().Id.Value);Assert.NotNull(s.VillageView());Assert.False(s.VillageView()!.CanPromise);Assert.Equal(ResultCode.NotAvailable,Act(s,VillageAction.ProposeRelief,amount:200).Code);Assert.DoesNotContain("HouseRice",System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.VillageView())));}
    [Fact]public void RemoteConversationAndCurrentReactionAreUnavailable(){var s=Start();Agree(s);Accepted(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:leave-village","castle"),s.Revision));Advance(s,1);Assert.Null(s.VillageView());Assert.Equal(ResultCode.NotAvailable,Act(s,VillageAction.ProposeRelief,amount:200).Code);}
    [Theory][InlineData(0)][InlineData(-1)][InlineData(3001)]public void InvalidReliefAmountsAreRejected(long n){var s=Start();Assert.Equal(ResultCode.NotAvailable,Act(s,VillageAction.ProposeRelief,amount:n).Code);Assert.Empty(s.DiagnosticSnapshot().Villages!.Entries);}
    [Fact]public void DuplicateAndStaleRequestsCannotExecuteTwice(){var s=Start();var q=Agree(s);var i=new VillageInput(new("request:once"),VillageAction.Deliver,Site,q,100);long rev=s.Revision;Accepted(s.ConsultVillage(i,s.PlayerControl,rev));Assert.Equal(ResultCode.AlreadyAccepted,s.ConsultVillage(i,s.PlayerControl,rev).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.ConsultVillage(i with{Amount=99},s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.StateChanged,s.ConsultVillage(i with{Id=new("request:old-view")},s.PlayerControl,rev).Code);Assert.Equal(2900,A(s).HouseRice);}
    [Fact]public void CrossModuleIdsConflict(){var s=Start();Propose(s);var id=s.DiagnosticSnapshot().Villages!.Entries.Single().Input.Id;Assert.Equal(ResultCode.IdPayloadConflict,s.ManageCommunity(new(id,Site,EconomyAction.RelieveVillage,1),s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),id.Value,"castle"),s.Revision).Code);}
    [Fact]public void ForgedProposalOrOrganizationCannotLoad(){var s=Start();Agree(s);var w=s.DiagnosticSnapshot();w.Villages=w.Villages! with{Proposals=[w.Villages.Proposals[0] with{Reply="改竄"}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));w=s.DiagnosticSnapshot();w.Villages=w.Villages! with{Organizations=[]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void LegacyV4BytesRemainUnchangedAndRejectInjectedVillages(){var s=HouseSalaryTests.Start();var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("Villages",System.Text.Encoding.UTF8.GetString(bytes));Assert.Equal(bytes,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(bytes)).DiagnosticSnapshot()));var w=s.DiagnosticSnapshot();w.Villages=Start().DiagnosticSnapshot().Villages;Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]
    public void ActualGenerationRecoveryAndFutureWorldMatch(int phase){var a=Start();var q=phase==0?Propose(a):Agree(a,phase==3);if(phase==2)Accepted(Act(a,VillageAction.Deliver,q,100));if(phase==3)Accepted(Act(a,VillageAction.Deliver,q,200));if(phase==4)Advance(a,8*86400);a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"village-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"village",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("village"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(a.VillageView()),ContractJson.Write(b.VillageView()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"village-"+phase+".before.json"),ContractJson.Write(a.DiagnosticSnapshot()));File.WriteAllBytes(Path.Combine(dir,"village-"+phase+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}foreach(var s in new[]{a,b}){if(phase==0)Accepted(Act(s,VillageAction.Confirm,q));if(phase<3)Accepted(Act(s,VillageAction.Deliver,q,phase==2?100:200));Advance(s,s.Seconds+10*86400);}Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(a.VillageView()),ContractJson.Write(b.VillageView()));}

    [Fact]public void HungryVillageRefusesLaborAndReliefClearsActualHunger(){var s=HungrySetup(false);Assert.True(A(s).Hunger>0);Propose(s,true);Assert.False(s.VillageView()!.Proposals.Last().Agreed);var q=Agree(s,amount:1000);Accepted(Act(s,VillageAction.Deliver,q,1000));Assert.Equal(0,A(s).Hunger);Assert.Equal(5000,A(s).HouseRice);}
    [Fact]public void WorkPausesOnFoodShortageAndReliefResumesSameLabor(){var s=HungrySetup(true);Assert.True(A(s).Hunger>0);Assert.Null(A(s).WorkDue);Assert.Equal(20,A(s).Reserved);var aid=Agree(s,amount:1000);Accepted(Act(s,VillageAction.Deliver,aid,1000));Assert.NotNull(A(s).WorkDue);Advance(s,A(s).WorkDue!.Value);Assert.Equal(110,A(s).Water);Assert.Equal(0,A(s).Reserved);}
    [Fact]public void DistantVillageCannotAlterLocalReplyOrPromise(){var s=Start();var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ConsultVillage(new(new("request:foreign-village"),VillageAction.ProposeRelief,new("site:odawara"),Amount:200),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void WorkCannotBeCreditedAsCompletedAtStart(){var s=Start();var q=Agree(s,true);Accepted(Act(s,VillageAction.Deliver,q,200));Assert.DoesNotContain("評価",s.VillageView()!.Reaction);Advance(s,7*86400);Assert.Contains("評価",s.VillageView()!.Reaction);}
    static WorldSession HungrySetup(bool work){var s=Start(seed:1);long Day(int y,int m,int d)=>(new DateOnly(y,m,d).DayNumber-new DateOnly(1560,1,1).DayNumber)*86400L;Advance(s,Day(1560,10,1));Accepted(s.ManageCommunity(new(new("request:levy"),Site,EconomyAction.CollectLevy,3000),s.PlayerControl,s.Revision));Advance(s,Day(1561,6,30));if(work){var q=Agree(s,true);Accepted(Act(s,VillageAction.Deliver,q,200));}Advance(s,Day(1561,7,1));return s;}
    [Fact]public void NormalProfileBuildsVillageAlongsideSalaryTradeAndWork(){var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"salary-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:shingen",42,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.Policy,LocalInspectionFindings.Policy,WorkFollowup.Policy,null,VoyageExpense.Standard,NpcArmies.CompactCombatPolicy,VillageConsultation.Policy,PersonalCompanions.RetainerReleasePolicy,TruceNegotiations.Policy,PrivateInformation.Policy,PrivateStanddown.Policy);Assert.Equal(VillageConsultation.Policy,store.Read(p.Instance).EconomyPolicy);var s=new WorldSession(NewCampaignStore.Build(p));Assert.NotNull(s.SalaryView());Assert.NotNull(s.CommunityEconomyView());Assert.NotNull(s.RegionalTradeView());Assert.NotNull(s.VillageView());Assert.Equal(3,s.DiagnosticSnapshot().Villages!.Organizations.Length);}
    [Fact]public void LaterWorkDoesNotMakeEarlierCompletedWorkLookUnfinished(){var s=Start();var first=Agree(s,true);Accepted(Act(s,VillageAction.Deliver,first,200));Advance(s,7*86400);var second=Agree(s,true);Accepted(Act(s,VillageAction.Deliver,second,200));Assert.Equal("工事完了",s.VillageView()!.Promises.Single(p=>p.Id==first).Status);Assert.Contains("工事中",s.VillageView()!.Promises.Single(p=>p.Id==second).Status);}
}
